//! `wsock32.dll` proxy for `lotrbfme.exe` (BFME 1.03): socket virtualisation for
//! BFME Beacon (architecture §3, §4.2–§4.4, §5; spec 03 §8–§9, spec 04 §3, §5).
//!
//! * Exports every name/ordinal of the system `SysWOW64\wsock32.dll`
//!   (`wsock32.def`, generated by `tools/gen_def.py`): 27 are implemented here
//!   (`exports`), the rest are forwarders exactly as in the system DLL.
//! * **Passive** unless `BEACON_AGENT_PORT` is set *and* the host is the identified
//!   `lotrbfme.exe` 1.03: then every export simply calls ws2_32 (or the exact copy
//!   of the WinSock 1.1 code in `compat`), nothing is patched or logged.
//! * **Armed**: `DllMain` patches the exe's WS2_32 IAT slots (+ `RegQueryValueExA/W`
//!   for the `ergc` CD key, + mutex/AppData hooks in test mode) and the exports
//!   virtualise the game's UDP sockets onto the loopback agent (`vsock`).
//!
//! No threads, no allocation on the hot path, no panics (`panic = "abort"` profile,
//! no `unwrap`/indexing on runtime data).

#![cfg(windows)]
#![deny(unsafe_op_in_unsafe_fn)]
#![warn(clippy::undocumented_unsafe_blocks)]
#![cfg_attr(
    not(test),
    deny(
        clippy::unwrap_used,
        clippy::expect_used,
        clippy::panic,
        clippy::indexing_slicing,
        clippy::unreachable,
        clippy::todo,
        clippy::unimplemented
    )
)]

mod compat;
mod config;
mod exports;
mod ffi;
mod iat;
mod init;
mod log;
mod multi;
mod pe;
mod reg;
mod state;
mod vsock;
mod vtable;
mod wide;
mod ws2;

use core::ffi::c_void;

/// Identification marker of this DLL: `BFME-BEACON-HOOK/<crate version>` + NUL.
///
/// The launcher searches the file for the prefix `BFME-BEACON-HOOK/` before it
/// replaces a `wsock32.dll` in the game folder: only a DLL containing it is treated
/// as Beacon's own hook (a foreign `wsock32.dll` is never overwritten). Not exported;
/// `DllMain` references it so the linker keeps the bytes in the image.
pub(crate) static BEACON_HOOK_MARKER: &[u8] =
    concat!("BFME-BEACON-HOOK/", env!("CARGO_PKG_VERSION"), "\0").as_bytes();

/// DLL entry point (called by the mingw CRT's `DllMainCRTStartup`).
///
/// Only `DLL_PROCESS_ATTACH` does work (see `init::process_attach`); it never
/// fails the load: on any problem the hook stays passive.
#[no_mangle]
pub extern "system" fn DllMain(_module: *mut c_void, reason: u32, _reserved: *mut c_void) -> i32 {
    if reason == ffi::DLL_PROCESS_ATTACH {
        // Keeps the marker in the image (dead-code elimination would drop it).
        core::hint::black_box(BEACON_HOOK_MARKER.as_ptr());
        init::process_attach();
    }
    1
}

#[cfg(test)]
mod marker_tests {
    #[test]
    fn marker_names_the_crate_version() {
        let text = core::str::from_utf8(super::BEACON_HOOK_MARKER).unwrap();
        assert_eq!(text, format!("BFME-BEACON-HOOK/{}\0", env!("CARGO_PKG_VERSION")));
    }
}
